  $db->exec("CREATE TABLE IF NOT EXISTS device_workspaces (device_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL UNIQUE,relative_path TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)");
